// ---------------------------------------------------------------------------
// Low-carb, healthy-fat (LCHF) recipes from "Low Carb Miracle" — the recipe
// book of Narayana Nethralaya's Reversing Diabetes Clinic (revised edition,
// Pushpa & Prof. K Krishnappa, guided by Dr K Bhujang Shetty).
//
// Ingredient amounts follow the book (fat included as written). The book's own
// nutrition tables are not used — many are internally inconsistent — so, like
// every other dish, nutrients are computed from the ingredient weights.
// Conventions used when converting the book's household measures:
//   1 cup ≈ 240 ml · 1 tbsp ≈ 15 ml (oil/ghee/butter ≈ 14 g, seeds ≈ 9–12 g)
//   1 tsp ≈ 5 ml (oil ≈ 4.5 g) · 1 almond ≈ 1.2 g · 1 cheese slice ≈ 20 g
//   Frying oil (deep or shallow) is counted at half the amount used — roughly
//   what the food absorbs. Every dish is per ONE unit (1 dosa, 1 katori …).
// ---------------------------------------------------------------------------

import type { MealTime } from "../types";
import type { DishDef, DishUnit } from "./types";

const katori = (def = 1, note = "≈150 g"): DishUnit => ({ label: "katori", plural: "katoris", default: def, step: 0.5, min: 0.5, max: 2.5, note });
const bowl = (def = 1, note = "≈200 ml"): DishUnit => ({ label: "bowl", plural: "bowls", default: def, step: 0.5, min: 0.5, max: 2, note });
const plate = (def = 1, note?: string): DishUnit => ({ label: "plate", plural: "plates", default: def, step: 0.5, min: 0.5, max: 2, note });
const glass = (note = "≈250 ml"): DishUnit => ({ label: "glass", plural: "glasses", default: 1, step: 0.5, min: 0.5, max: 2, note });
const cup = (note = "≈150 ml"): DishUnit => ({ label: "cup", plural: "cups", default: 1, step: 0.5, min: 0.5, max: 2, note });
const serving = (note?: string, def = 1): DishUnit => ({ label: "serving", plural: "servings", default: def, step: 0.5, min: 0.5, max: 2, note });
const tbsp = (note = "≈15 g"): DishUnit => ({ label: "tbsp", plural: "tbsp", default: 1, step: 1, min: 1, max: 3, note });
const pcs = (label: string, plural: string, def: number, min: number, max: number, note?: string): DishUnit => ({ label, plural, default: def, step: 1, min, max, note });

const EM: MealTime[] = ["earlyMorning"];
const B: MealTime[] = ["breakfast"];
const MM: MealTime[] = ["midMorning"];
const ES: MealTime[] = ["eveningSnack"];
const LD: MealTime[] = ["lunch", "dinner"];

/** Coach's choice: every recipe from this book is marked as suiting these conditions. */
const GOOD = ["diabetes", "insulin-resistance", "weight-loss"] as DishDef["goodFor"];

/** Shared fields for every LCHF dish. */
const lc = (d: Omit<DishDef, "goodFor" | "gi"> & { gi?: DishDef["gi"] }): DishDef => ({
  gi: "low",
  ...d,
  tags: ["low-carb", ...(d.tags ?? [])],
  goodFor: GOOD,
});

